description:
Make potty training less stressful for both you and your child with the Fisher-Price Fun to Learn Potty. Designed for use with children nine months to three years old, this responsive potty encourages the transition from a potty seat to a grown-up toilet while helping to build your child's confidence and keeping toilet training fun. It requires three "C" batteries (not included).PositionX = 10; PositionY = 10; defaultWidth = 600; defaultHeight = 400; var AutoClose = true; function popImage(imageURL,imageTitle){  var imgWin = window.open('','_blank','scrollbars=no,resizable=1,width='+defaultWidth+',height='+defaultHeight+',left='+PositionX+',top='+PositionY);  if( !imgWin ) { return true; } //popup blockers should not cause errors  imgWin.document.write('<html><head><title>'+imageTitle+'</title><script type="text/javascript">
'+   'function resizeWinTo() {
'+   'if( !document.images.length ) { document.images[0] = document.layers[0].images[0]; }'+   'var oH = document.images[0].height, oW = document.images[0].width;
'+   'if( !oH || window.doneAlready ) { return; }
'+ //in case images are disabled   'window.doneAlready = true;
'+ //for Safari and Opera   'var x = window; x.resizeTo( oW + 200, oH + 200 );
'+   'var myW = 0, myH = 0, d = x.document.documentElement, b = x.document.body;
'+   'if( x.innerWidth ) { myW = x.innerWidth; myH = x.innerHeight; }
'+   'else if( d && d.clientWidth ) { myW = d.clientWidth; myH = d.clientHeight; }
'+   'else if( b && b.clientWidth ) { myW = b.clientWidth; myH = b.clientHeight; }
'+   'if( window.opera && !document.childNodes ) { myW += 16; }
'+   'x.resizeTo( oW = oW + ( ( oW + 200 ) - myW ), oH = oH + ( (oH + 200 ) - myH ) );
'+   'var scW = screen.availWidth ? screen.availWidth : screen.width;
'+   'var scH = screen.availHeight ? screen.availHeight : screen.height;
'+   'if( !window.opera ) { x.moveTo(Math.round((scW-oW)/2),Math.round((scH-oH)/2)); }
'+   '}
'+   '</script>'+   '</head><body onload="resizeWinTo();"'+(AutoClose?' onblur="self.close();"':'')+'>'+   (document.layers?('<layer left="0" top="0">'):('

